    expect(total([1, 2, 3])).toBe(6);
    expect(total([1.5, 2.5])).toBe(4);
  });

  it('should throw for non-numeric values', () => {
    expect(() => total([1, 'a'])).toThrow();
  });

  it('should throw for non-finite values', () => {
    expect(() => total([1, Infinity])).toThrow();
  });
});

