const { exec } = require('child_process');
const { stdout, stderr } = process.stdout;

const args = process.argv.slice(2);
let sum = 0;

args.forEach(arg => {
  if (!isNaN(Number(arg))) {
    sum += Number(arg);
  } else {
    console.error('Non-numeric argument found:', arg);
    process.exit(1);
  }
});

if (sum === 0) {
  console.log(0);
} else {
  console.log(sum);
};
